UPDATE ${database.prefix.userms}hou_base_modularizationd set page_name =#{param.pageName} , page_data =#{param.pageData} ,
page_type =#{param.pageType} ,create_time =now(),page_is_index = #{param.pageIsIndex},
goodsAllIdJson =#{param.goodsAllIdJson}

    , page_platform = #{param.pagePlatform}

where page_id = #{param.pageId}

mapper.select:
select page_id,page_name,page_data,page_type,page_start,page_default,create_time,page_is_index,page_template_code,page_platform
from ${database.prefix.userms}hou_base_modularizationd where page_default = 0

    and page_is_index = #{param.pageIsIndex}


    and page_name  LIKE CONCAT('%',#{param.pageName},'%')


    and page_id  = #{param.pageId}


    and page_is_index  = #{param.pageIsIndex}



    and page_platform = #{param.pagePlatform}

ORDER BY create_time desc
